using ProjetoIntegradorBack.Domain.Enums; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Domain.Models; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class RelatorioRepository(ProjetoIntegradorBackDbContext context):IRelatorioRepository{
public async Task<Result<IReadOnlyList<ComissaoFuncionarioInfo>>> ObterComissoesPorMesAsync(Guid estabelecimentoId,int mes,int ano,Guid? funcionarioId,CancellationToken ct=default){try{var q=context.Agendamentos.Include(x=>x.Funcionario).Where(x=>x.EstabelecimentoId==estabelecimentoId&&x.Status==StatusAgendamento.Concluido&&x.DataHora.Month==mes&&x.DataHora.Year==ano);if(funcionarioId.HasValue)q=q.Where(x=>x.FuncionarioId==funcionarioId);var a=await q.ToListAsync(ct);var r=a.GroupBy(x=>x.FuncionarioId).Select(g=>new ComissaoFuncionarioInfo{FuncionarioId=g.Key,NomeFuncionario=g.First().Funcionario.Nome,Funcao=g.First().Funcionario.Funcao,PercentualComissao=g.First().Funcionario.PercentualComissao,TotalAtendimentos=g.Count(),FaturamentoBruto=g.Sum(x=>x.ValorTotal),ValorComissao=g.Sum(x=>x.ValorTotal)*g.First().Funcionario.PercentualComissao/100}).ToList();return Result<IReadOnlyList<ComissaoFuncionarioInfo>>.AsSuccess(r);}catch(Exception ex){return Result<IReadOnlyList<ComissaoFuncionarioInfo>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<ResumoAtendimentosInfo>> ObterResumoAtendimentosAsync(Guid id,DateTime inicio,DateTime fim,CancellationToken ct=default){try{var a=await context.Agendamentos.Where(x=>x.EstabelecimentoId==id&&x.DataHora>=inicio&&x.DataHora<=fim).ToListAsync(ct);return Result<ResumoAtendimentosInfo>.AsSuccess(new ResumoAtendimentosInfo{TotalAgendamentos=a.Count,Confirmados=a.Count(x=>x.Status==StatusAgendamento.Confirmado),Concluidos=a.Count(x=>x.Status==StatusAgendamento.Concluido),Cancelados=a.Count(x=>x.Status==StatusAgendamento.Cancelado),FaturamentoTotal=a.Where(x=>x.Status==StatusAgendamento.Concluido).Sum(x=>x.ValorTotal)});}catch(Exception ex){return Result<ResumoAtendimentosInfo>.AsFailure(new Failure(500,ex.Message));}}}